pm.collectionVariables.set("otherHostToken", json.token);

pm.test("Status is 201 and password_hash is hidden", function () {
  pm.response.to.have.status(201);
  const json = pm.response.json();
  pm.expect(json.user.role).to.eql("PLAYER");
  pm.expect(json.user.password_hash).to.be.undefined;
});
pm.collectionVariables.set("newUserId", pm.response.json().user.user_id);
