pm.test("Status code is 201", function () {
    pm.response.to.have.status(201);
});

// Save the created ID for later requests
pm.collectionVariables.set("setId", pm.response.json().id);

pm.test("Status is 201", function () {
  pm.response.to.have.status(201);
});
const jsonData = pm.response.json();
const dynamicCode = jsonData.data ? jsonData.data.code : jsonData.code;
pm.collectionVariables.set("code", dynamicCode);

// Automatically clears the old session code right before creating a new one
pm.environment.unset("code");
pm.collectionVariables.unset("code");

pm.test("Create set returns 201", () => pm.response.to.have.status(201));
const json = pm.response.json();
pm.collectionVariables.set("m2SetId", json.id);

pm.test("Paginated list returns 200 with envelope", () => {
  pm.response.to.have.status(200);
  const json = pm.response.json();
  pm.expect(json.data).to.be.an("array");
  pm.expect(json.meta).to.include.all.keys("page", "limit", "total", "pages");
  pm.expect(json.meta.page).to.eql(1);
  pm.expect(json.meta.limit).to.eql(2);
});

pm.test("Empty search returns 200 with empty data array", () => {
  pm.response.to.have.status(200);
  const json = pm.response.json();
  pm.expect(json.data).to.be.an("array").that.is.empty;
  pm.expect(json.meta.total).to.eql(0);
});

pm.test("Create question returns 201 with choices", () => {
  pm.response.to.have.status(201);
  const json = pm.response.json();
  pm.expect(json.position).to.eql(1);
  pm.expect(json.choices).to.have.lengthOf(3);
  pm.collectionVariables.set("m2QuestionId", json.id);
});

